-- ----------------------------
-- Table structure for dev_artifact
-- ----------------------------
DROP TABLE IF EXISTS `dev_artifact`;
CREATE TABLE `dev_artifact`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `project_id` bigint NOT NULL COMMENT '任务编号，关联 dev_project.id',
  `type` tinyint NOT NULL COMMENT '产物类型：1-设计文档 2-代码 3-使用说明',
  `version` int NOT NULL DEFAULT 1 COMMENT '版本号，同一任务同一类型从 1 递增',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态：0-AI 生成 1-人工修改 2-已定稿',
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '产物内容（Markdown/代码）',
  `remark` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '生成该版本的依据（如评审意见）',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_project_id`(`project_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'AI 开发阶段产物' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of dev_artifact
-- ----------------------------
INSERT INTO `dev_artifact` VALUES (1, 1, 1, 1, 2, '# 用户反馈管理模块概要设计文档\n\n## 1. 概述\n\n本模块用于建设统一的用户反馈渠道，解决当前用户反馈依赖客服电话、信息分散且无法追溯的问题，支持普通用户提交反馈并凭反馈编号查询处理进度、查看本人反馈状态，支持管理员查看全部反馈、对反馈进行回复或关闭处理，并按反馈类型进行数量统计，形成可管理、可追溯的用户反馈处理流程。\n\n---\n\n## 2. 功能清单\n\n| 编号 | 功能点 | 使用角色 | 优先级 | 功能说明 |\n|---|---|---:|---:|---|\n| FB-01 | 提交反馈 | 普通用户 | P0 | 用户填写反馈标题、反馈内容、反馈类型并提交，系统校验必填项与长度，提交成功后生成反馈编号 |\n| FB-02 | 凭编号查询处理进度 | 普通用户 | P0 | 用户输入反馈编号查询反馈当前处理状态、回复内容等进度信息 |\n| FB-03 | 查看我的反馈状态 | 普通用户 | P0 | 普通用户查看自己提交的反馈列表及处理状态 |\n| FB-04 | 管理员查看反馈列表 | 管理员 | P0 | 管理员分页查看全部用户提交的反馈信息 |\n| FB-05 | 回复反馈 | 管理员 | P0 | 管理员对反馈填写回复内容，更新反馈处理状态 |\n| FB-06 | 关闭反馈 | 管理员 | P0 | 管理员关闭反馈，更新反馈处理状态 |\n| FB-07 | 按反馈类型统计 | 管理员 | P1 | 管理员查看功能异常、体验问题、功能建议、其他四类反馈的数量统计 |\n\n---\n\n## 3. 数据库设计\n\n### 3.1 表名：`user_feedback`\n\n用于存储用户提交的反馈信息及管理员处理信息。\n\n| 字段名 | 类型 | 是否必填 | 默认值 | 注释 |\n|---|---|---:|---:|---|\n| `id` | `BIGINT UNSIGNED` | 是 | 自增 | 主键 ID |\n| `feedback_no` | `VARCHAR(32)` | 是 | 无 | 反馈编号，全局唯一 |\n| `user_id` | `BIGINT UNSIGNED` | 是 | 无 | 提交反馈的用户 ID |\n| `title` | `VARCHAR(50)` | 是 | 无 | 反馈标题，最大 50 字 |\n| `content` | `VARCHAR(1000)` | 是 | 无 | 反馈内容，最大 1000 字 |\n| `feedback_type` | `TINYINT` | 是 | 无 | 反馈类型：1-功能异常，2-体验问题，3-功能建议，4-其他 |\n| `status` | `TINYINT` | 是 | 1 | 处理状态：1-待处理，2-已回复，3-已关闭 |\n| `reply_content` | `TEXT` | 否 | 无 | 管理员回复内容 |\n| `reply_time` | `DATETIME` | 否 | 无 | 回复时间 |\n| `close_time` | `DATETIME` | 否 | 无 | 关闭时间 |\n| `handler_id` | `BIGINT UNSIGNED` | 否 | 无 | 最后处理人 ID，记录回复或关闭操作的管理员 |\n| `handler_name` | `VARCHAR(64)` | 否 | 无 | 最后处理人姓名 |\n| `creator` | `BIGINT UNSIGNED` | 是 | 无 | 创建人 ID，提交反馈的用户 ID |\n| `create_time` | `DATETIME` | 是 | `CURRENT_TIMESTAMP` | 创建时间 |\n| `updater` | `BIGINT UNSIGNED` | 是 | 无 | 更新人 ID，最后修改该记录的用户或管理员 |\n| `update_time` | `DATETIME` | 是 | `CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP` | 更新时间 |\n| `deleted` | `TINYINT` | 是 | 0 | 逻辑删除标识：0-未删除，1-已删除 |\n\n#### 索引设计\n\n| 索引名 | 字段 | 类型 | 说明 |\n|---|---|---|---|\n| `PRIMARY` | `id` | 主键 | 主键索引 |\n| `uk_feedback_no` | `feedback_no` | 唯一索引 | 保证反馈编号唯一 |\n| `idx_user_id` | `user_id` | 普通索引 | 支持查询用户本人反馈 |\n| `idx_status` | `status` | 普通索引 | 支持按状态查询 |\n| `idx_feedback_type` | `feedback_type` | 普通索引 | 支持按类型统计与查询 |\n| `idx_create_time` | `create_time` | 普通索引 | 支持按提交时间排序或查询 |\n\n> 当前需求未定义删除功能，`deleted` 字段作为基础逻辑删除字段预留，所有查询默认过滤 `deleted = 0`。\n\n---\n\n### 3.2 枚举定义\n\n#### 反馈类型：`FeedbackTypeEnum`\n\n| 枚举值 | 编码 | 说明 |\n|---|---:|---|\n| `FUNCTION_ERROR` | 1 | 功能异常 |\n| `EXPERIENCE_ISSUE` | 2 | 体验问题 |\n| `FUNCTION_SUGGESTION` | 3 | 功能建议 |\n| `OTHER` | 4 | 其他 |\n\n#### 处理状态：`FeedbackStatusEnum`\n\n| 枚举值 | 编码 | 说明 |\n|---|---:|---|\n| `PENDING` | 1 | 待处理 |\n| `REPLIED` | 2 | 已回复 |\n| `CLOSED` | 3 | 已关闭 |\n\n---\n\n## 4. 接口设计\n\n### 4.1 统一约定\n\n所有接口统一返回 `Result<T>` 结构。\n\n| 字段名 | 类型 | 说明 |\n|---|---|---|\n| `code` | `Integer` | 响应码，0 表示成功，非 0 表示失败 |\n| `message` | `String` | 响应信息 |\n| `data` | `T` | 业务数据 |\n\n分页接口统一返回 `Result<PageResultVO<T>>`。\n\n| 字段名 | 类型 | 说明 |\n|---|---|---|\n| `total` | `Long` | 总记录数 |\n| `records` | `List<T>` | 当前页数据 |\n\n时间字段统一使用 `yyyy-MM-dd HH:mm:ss` 格式返回。\n\n---\n\n### 4.2 接口列表\n\n| 编号 | 接口名称 | 路径 | 请求方式 | 入参 VO | 出参 VO | 说明 |\n|---|---|---|---|---|---|---|\n| API-01 | 提交反馈 | `/api/feedback/submit` | `POST` | `FeedbackSubmitVO` | `Result<FeedbackSubmitResultVO>` | 普通用户提交反馈 |\n| API-02 | 凭编号查询处理进度 | `/api/feedback/progress` | `GET` | `FeedbackProgressQueryVO` | `Result<FeedbackProgressVO>` | 根据反馈编号查询处理进度 |\n| API-03 | 查询我的反馈列表 | `/api/feedback/my/list` | `GET` | `FeedbackMyQueryVO` | `Result<PageResultVO<FeedbackMyVO>>` | 普通用户分页查询本人反馈 |\n| API-04 | 管理员查看反馈列表 | `/api/admin/feedback/list` | `GET` | `AdminFeedbackQueryVO` | `Result<PageResultVO<AdminFeedbackVO>>` | 管理员分页查看全部反馈 |\n| API-05 | 回复反馈 | `/api/admin/feedback/reply` | `POST` | `FeedbackReplyVO` | `Result<FeedbackHandleResultVO>` | 管理员回复反馈 |\n| API-06 | 关闭反馈 | `/api/admin/feedback/close` | `POST` | `FeedbackCloseVO` | `Result<FeedbackHandleResultVO>` | 管理员关闭反馈 |\n| API-07 | 按反馈类型统计 | `/api/admin/feedback/statistics/type` | `GET` | `FeedbackTypeStatQueryVO` | `Result<List<FeedbackTypeStatVO>>` | 管理员查看各类型反馈数量 |\n\n---\n\n### 4.3 VO 定义\n\n#### 4.3.1 `FeedbackSubmitVO`\n\n提交反馈入参。\n\n| 字段名 | 类型 | 必填 | 校验规则 | 说明 |\n|---|---|---:|---|---|\n| `title` | `String` | 是 | 非空，最大 50 字 | 反馈标题 |\n| `content` | `String` | 是 | 非空，最大 1000 字 | 反馈内容 |\n| `feedbackType` | `Integer` | 是 | 取值 1-4 | 反馈类型 |\n\n---\n\n#### 4.3.2 `FeedbackSubmitResultVO`\n\n提交反馈出参。\n\n| 字段名 | 类型 | 说明 |\n|---|---|---|\n| `feedbackNo` | `String` | 反馈编号 |\n\n---\n\n#### 4.3.3 `FeedbackProgressQueryVO`\n\n凭编号查询处理进度入参。\n\n| 字段名 | 类型 | 必填 | 校验规则 | 说明 |\n|---|---|---:|---|---|\n| `feedbackNo` | `String` | 是 | 非空，最大 32 字 | 反馈编号 |\n\n---\n\n#### 4.3.4 `FeedbackProgressVO`\n\n凭编号查询处理进度出参。\n\n| 字段名 | 类型 | 说明 |\n|---|---|---|\n| `feedbackNo` | `String` | 反馈编号 |\n| `title` | `String` | 反馈标题 |\n| `feedbackType` | `Integer` | 反馈类型编码 |\n| `feedbackTypeDesc` | `String` | 反馈类型描述 |\n| `status` | `Integer` | 处理状态编码 |\n| `statusDesc` | `String` | 处理状态描述 |\n| `createTime` | `LocalDateTime` | 提交时间 |\n| `replyContent` | `String` | 回复内容，未回复时为空 |\n| `replyTime` | `LocalDateTime` | 回复时间，未回复时为空 |\n| `closeTime` | `LocalDateTime` | 关闭时间，未关闭时为空 |\n\n---\n\n#### 4.3.5 `FeedbackMyQueryVO`\n\n查询我的反馈列表入参。\n\n| 字段名 | 类型 | 必填 | 校验规则 | 说明 |\n|---|---|---:|---|---|\n| `pageNo` | `Integer` | 是 | 默认 1，最小 1 | 页码 |\n| `pageSize` | `Integer` | 是 | 默认 10，范围 1-100 | 每页条数 |\n\n---\n\n#### 4.3.6 `FeedbackMyVO`\n\n我的反馈列表出参。\n\n| 字段名 | 类型 | 说明 |\n|---|---|---|\n| `id` | `Long` | 反馈记录 ID |\n| `feedbackNo` | `String` | 反馈编号 |\n| `title` | `String` | 反馈标题 |\n| `feedbackType` | `Integer` | 反馈类型编码 |\n| `feedbackTypeDesc` | `String` | 反馈类型描述 |\n| `status` | `Integer` | 处理状态编码 |\n| `statusDesc` | `String` | 处理状态描述 |\n| `createTime` | `LocalDateTime` | 提交时间 |\n| `replyContent` | `String` | 回复内容，未回复时为空 |\n| `replyTime` | `LocalDateTime` | 回复时间，未回复时为空 |\n\n---\n\n#### 4.3.7 `AdminFeedbackQueryVO`\n\n管理员查看反馈列表入参。\n\n| 字段名 | 类型 | 必填 | 校验规则 | 说明 |\n|---|---|---:|---|---|\n| `pageNo` | `Integer` | 是 | 默认 1，最小 1 | 页码 |\n| `pageSize` | `Integer` | 是 | 默认 10，范围 1-100 | 每页条数 |\n\n---\n\n#### 4.3.8 `AdminFeedbackVO`\n\n管理员反馈列表出参。\n\n| 字段名 | 类型 | 说明 |\n|---|---|---|\n| `id` | `Long` | 反馈记录 ID |\n| `feedbackNo` | `String` | 反馈编号 |\n| `userId` | `Long` | 提交用户 ID |\n| `title` | `String` | 反馈标题 |\n| `content` | `String` | 反馈内容 |\n| `feedbackType` | `Integer` | 反馈类型编码 |\n| `feedbackTypeDesc` | `String` | 反馈类型描述 |\n| `status` | `Integer` | 处理状态编码 |\n| `statusDesc` | `String` | 处理状态描述 |\n| `createTime` | `LocalDateTime` | 提交时间 |\n| `replyContent` | `String` | 回复内容 |\n| `replyTime` | `LocalDateTime` | 回复时间 |\n| `closeTime` | `LocalDateTime` | 关闭时间 |\n| `handlerName` | `String` | 最后处理人姓名 |\n\n---\n\n#### 4.3.9 `FeedbackReplyVO`\n\n回复反馈入参。\n\n| 字段名 | 类型 | 必填 | 校验规则 | 说明 |\n|---|---|---:|---|---|\n| `id` | `Long` | 是 | 非空 | 反馈记录 ID |\n| `replyContent` | `String` | 是 | 非空 | 回复内容，长度限制待确认 |\n\n---\n\n#### 4.3.10 `FeedbackCloseVO`\n\n关闭反馈入参。\n\n| 字段名 | 类型 | 必填 | 校验规则 | 说明 |\n|---|---|---:|---|---|\n| `id` | `Long` | 是 | 非空 | 反馈记录 ID |\n\n---\n\n#### 4.3.11 `FeedbackHandleResultVO`\n\n回复或关闭反馈出参。\n\n| 字段名 | 类型 | 说明 |\n|---|---|---|\n| `id` | `Long` | 反馈记录 ID |\n| `status` | `Integer` | 最新处理状态编码 |\n| `statusDesc` | `String` | 最新处理状态描述 |\n\n---\n\n#### 4.3.12 `FeedbackTypeStatQueryVO`\n\n按反馈类型统计入参。\n\n当前无查询条件，预留空 VO，便于后续扩展。\n\n| 字段名 | 类型 | 必填 | 说明 |\n|---|---|---:|---|\n| 无 | - | - | 当前无入参字段 |\n\n---\n\n#### 4.3.13 `FeedbackTypeStatVO`\n\n按反馈类型统计出参。\n\n| 字段名 | 类型 | 说明 |\n|---|---|---|\n| `feedbackType` | `Integer` | 反馈类型编码 |\n| `feedbackTypeDesc` | `String` | 反馈类型描述 |\n| `count` | `Long` | 该类型反馈数量 |\n\n---\n\n## 5. 后端设计\n\n### 5.1 分层类清单\n\n| 分层 | 类名 | 新增/修改 | 职责说明 |\n|---|---|---|---|\n| Controller | `FeedbackController` | 新增 | 提供普通用户端接口，包括提交反馈、凭编号查询处理进度、查询我的反馈列表 |\n| Controller | `AdminFeedbackController` | 新增 | 提供管理员端接口，包括反馈列表、回复、关闭、类型统计 |\n| Service | `FeedbackService` | 新增 | 定义普通用户反馈业务接口 |\n| Service | `AdminFeedbackService` | 新增 | 定义管理员反馈处理业务接口 |\n| ServiceImpl | `FeedbackServiceImpl` | 新增 | 实现普通用户反馈提交、进度查询、我的反馈列表查询 |\n| ServiceImpl | `AdminFeedbackServiceImpl` | 新增 | 实现管理员反馈列表查询、回复、关闭、类型统计 |\n| DO | `UserFeedbackDO` | 新增 | 映射 `user_feedback` 表 |\n| Mapper | `UserFeedbackMapper` | 新增 | 提供 `user_feedback` 表数据访问方法 |\n| VO | `FeedbackSubmitVO` | 新增 | 提交反馈入参对象 |\n| VO | `FeedbackSubmitResultVO` | 新增 | 提交反馈出参对象 |\n| VO | `FeedbackProgressQueryVO` | 新增 | 凭编号查询处理进度入参对象 |\n| VO | `FeedbackProgressVO` | 新增 | 凭编号查询处理进度出参对象 |\n| VO | `FeedbackMyQueryVO` | 新增 | 我的反馈列表查询入参对象 |\n| VO | `FeedbackMyVO` | 新增 | 我的反馈列表出参对象 |\n| VO | `AdminFeedbackQueryVO` | 新增 | 管理员反馈列表查询入参对象 |\n| VO | `AdminFeedbackVO` | 新增 | 管理员反馈列表出参对象 |\n| VO | `FeedbackReplyVO` | 新增 | 回复反馈入参对象 |\n| VO | `FeedbackCloseVO` | 新增 | 关闭反馈入参对象 |\n| VO | `FeedbackHandleResultVO` | 新增 | 回复或关闭反馈出参对象 |\n| VO | `FeedbackTypeStatQueryVO` | 新增 | 类型统计入参对象，当前预留 |\n| VO | `FeedbackTypeStatVO` | 新增 | 类型统计出参对象 |\n| Enum | `FeedbackTypeEnum` | 新增 | 反馈类型枚举 |\n| Enum | `FeedbackStatusEnum` | 新增 | 反馈处理状态枚举 |\n| Converter | `UserFeedbackConverter` | 新增 | `UserFeedbackDO` 与 VO 之间转换 |\n| Generator | `FeedbackNoGenerator` | 新增 | 生成全局唯一反馈编号 |\n| ErrorCode | `FeedbackErrorCode` | 新增/修改 | 定义反馈模块业务错误码，如反馈不存在、状态不允许处理等 |\n\n---\n\n### 5.2 关键业务规则\n\n#### 5.2.1 提交反馈规则\n\n1. 用户必须登录。\n2. `title` 必填，长度不超过 50 字。\n3. `content` 必填，长度不超过 1000 字。\n4. `feedbackType` 必填，取值范围为 1-4。\n5. 提交成功后生成 `feedbackNo`。\n6. 初始状态 `status = 1`，即待处理。\n7. `creator` 和 `updater` 均设置为当前登录用户 ID。\n8. `deleted` 设置为 0。\n\n---\n\n#### 5.2.2 凭编号查询处理进度规则\n\n1. 根据 `feedbackNo` 查询未删除反馈。\n2. 若反馈不存在，返回业务错误。\n3. 返回反馈标题、类型、状态、回复内容、回复时间、关闭时间等信息。\n4. 是否仅允许查询本人反馈，待确认。\n\n---\n\n#### 5.2.3 我的反馈列表规则\n\n1. 根据当前登录用户 ID 查询本人反馈。\n2. 默认按 `create_time` 倒序排列。\n3. 支持分页。\n4. 仅查询 `deleted = 0` 的数据。\n\n---\n\n#### 5.2.4 管理员反馈列表规则\n\n1. 管理员可查看全部未删除反馈。\n2. 默认按 `create_time` 倒序排列。\n3. 支持分页。\n4. 当前需求未要求筛选条件，仅设计分页查询；是否需要筛选待确认。\n\n---\n\n#### 5.2.5 回复反馈规则\n\n1. 管理员必须登录且具有管理员权限。\n2. 根据反馈 ID 查询未删除反馈。\n3. 若反馈不存在，返回业务错误。\n4. 允许回复的状态：`PENDING`、`REPLIED`。\n5. 回复成功后更新：\n   - `reply_content`\n   - `reply_time`\n   - `status = 2`\n   - `handler_id`\n   - `handler_name`\n   - `updater`\n6. 已关闭反馈是否允许回复，待确认。\n\n---\n\n#### 5.2.6 关闭反馈规则\n\n1. 管理员必须登录且具有管理员权限。\n2. 根据反馈 ID 查询未删除反馈。\n3. 若反馈不存在，返回业务错误。\n4. 允许关闭的状态：`PENDING`、`REPLIED`。\n5. 关闭成功后更新：\n   - `close_time`\n   - `status = 3`\n   - `handler_id`\n   - `handler_name`\n   - `updater`\n6. 已关闭反馈是否允许重新打开，待确认。\n\n---\n\n#### 5.2.7 按类型统计规则\n\n1. 统计范围为未删除反馈。\n2. 按 `feedback_type` 分组统计数量。\n3. 固定返回四类：功能异常、体验问题、功能建议、其他。\n4. 某类型无数据时，`count` 返回 0。\n\n---\n\n### 5.3 Service 方法设计\n\n#### `FeedbackService`\n\n| 方法名 | 入参 | 出参 | 说明 |\n|---|---|---|---|\n| `submit` | `FeedbackSubmitVO`, `Long userId` | `FeedbackSubmitResultVO` | 提交反馈 |\n| `queryProgress` | `FeedbackProgressQueryVO` | `FeedbackProgressVO` | 凭编号查询处理进度 |\n| `queryMyList` | `FeedbackMyQueryVO`, `Long userId` | `PageResultVO<FeedbackMyVO>` | 查询当前用户反馈列表 |\n\n---\n\n#### `AdminFeedbackService`\n\n| 方法名 | 入参 | 出参 | 说明 |\n|---|---|---|---|\n| `queryList` | `AdminFeedbackQueryVO` | `PageResultVO<AdminFeedbackVO>` | 查询全部反馈列表 |\n| `reply` | `FeedbackReplyVO`, `Long adminId`, `String adminName` | `FeedbackHandleResultVO` | 回复反馈 |\n| `close` | `FeedbackCloseVO`, `Long adminId`, `String adminName` | `FeedbackHandleResultVO` | 关闭反馈 |\n| `statisticsByType` | `FeedbackTypeStatQueryVO` | `List<FeedbackTypeStatVO>` | 按反馈类型统计 |\n\n---\n\n### 5.4 Mapper 方法设计\n\n| 方法名 | 入参 | 出参 | 说明 |\n|---|---|---|---|\n| `insert` | `UserFeedbackDO` | `int` | 新增反馈记录 |\n| `selectById` | `Long id` | `UserFeedbackDO` | 根据 ID 查询反馈 |\n| `selectByFeedbackNo` | `String feedbackNo` | `UserFeedbackDO` | 根据反馈编号查询反馈 |\n| `selectPageByUser` | `Page<UserFeedbackDO>`, `Long userId` | `Page<UserFeedbackDO>` | 分页查询用户本人反馈 |\n| `selectPageAdmin` | `Page<UserFeedbackDO>`, `AdminFeedbackQueryVO` | `Page<UserFeedbackDO>` | 分页查询全部反馈 |\n| `updateReply` | `Long id`, `String replyContent`, `LocalDateTime replyTime`, `Long handlerId`, `String handlerName`, `Long updater` | `int` | 更新回复信息 |\n| `updateClose` | `Long id`, `LocalDateTime closeTime`, `Long handlerId`, `String handlerName`, `Long updater` | `int` | 更新关闭信息 |\n| `countByType` | 无 | `List<FeedbackTypeStatVO>` | 按反馈类型统计数量 |\n\n---\n\n## 6. 前端设计\n\n### 6.1 用户端页面与组件\n\n| 页面/组件 | 类型 | 功能说明 | 对应后端接口 |\n|---|---|---|---|\n| `FeedbackSubmitForm` | 表单页面或弹窗 | 用户填写反馈标题、反馈内容、反馈类型并提交 | `POST /api/feedback/submit` |\n| `FeedbackSubmitSuccessResult` | 结果提示组件 | 提交成功后展示反馈编号，支持复制 | 无，展示接口返回的 `feedbackNo` |\n| `FeedbackProgressQueryForm` | 查询表单组件 | 用户输入反馈编号，查询处理进度 | `GET /api/feedback/progress` |\n| `FeedbackProgressResult` | 结果展示组件 | 展示反馈状态、回复内容、回复时间、关闭时间 | 展示 `FeedbackProgressVO` |\n| `MyFeedbackListPage` | 列表页面 | 展示当前用户提交的反馈列表及状态 | `GET /api/feedback/my/list` |\n| `MyFeedbackTable` | 表格组件 | 展示反馈编号、标题、类型、状态、提交时间、回复内容 | 展示 `FeedbackMyVO` |\n| `FeedbackTypeSelect` | 下拉选择组件 | 选择反馈类型，选项为功能异常、体验问题、功能建议、其他 | 无 |\n| `FeedbackStatusTag` | 状态标签组件 | 展示待处理、已回复、已关闭状态 | 无 |\n\n---\n\n### 6.2 管理端页面与组件\n\n| 页面/组件 | 类型 | 功能说明 | 对应后端接口 |\n|---|---|---|---|\n| `AdminFeedbackListPage` | 列表页面 | 管理员查看全部反馈，支持分页 | `GET /api/admin/feedback/list` |\n| `AdminFeedbackTable` | 表格组件 | 展示反馈编号、标题、内容、类型、状态、提交时间、回复内容、处理人 | 展示 `AdminFeedbackVO` |\n| `FeedbackDetailDrawer` | 详情抽屉 | 查看完整反馈内容、回复内容、处理信息 | 使用列表接口返回数据 |\n| `ReplyFeedbackDialog` | 回复弹窗 | 管理员填写回复内容并提交 | `POST /api/admin/feedback/reply` |\n| `CloseFeedbackConfirm` | 确认弹窗 | 管理员确认关闭反馈 | `POST /api/admin/feedback/close` |\n| `FeedbackTypeStatPanel` | 统计面板 | 展示各反馈类型数量，支持卡片或表格形式 | `GET /api/admin/feedback/statistics/type` |\n| `FeedbackStatusTag` | 状态标签组件 | 展示反馈处理状态 | 无 |\n| `Pagination` | 分页组件 | 管理列表与我的反馈列表分页 | 配合列表接口 |\n\n---\n\n### 6.3 前端交互说明\n\n#### 用户提交反馈\n\n1. 用户打开 `FeedbackSubmitForm`。\n2. 填写 `title`、`content`，选择 `feedbackType`。\n3. 前端校验必填项与最大长度。\n4. 调用 `POST /api/feedback/submit`。\n5. 提交成功后展示 `feedbackNo`。\n6. 用户可复制编号用于后续查询。\n\n---\n\n#### 用户查询处理进度\n\n1. 用户打开 `FeedbackProgressQueryForm`。\n2. 输入 `feedbackNo`。\n3. 调用 `GET /api/feedback/progress`。\n4. `FeedbackProgressResult` 展示状态与处理进度。\n\n---\n\n#### 管理员处理反馈\n\n1. 管理员进入 `AdminFeedbackListPage`。\n2. 列表调用 `GET /api/admin/feedback/list`。\n3. 管理员点击“回复”打开 `ReplyFeedbackDialog`。\n4. 填写回复内容后调用 `POST /api/admin/feedback/reply`。\n5. 管理员点击“关闭”打开 `CloseFeedbackConfirm`。\n6. 确认后调用 `POST /api/admin/feedback/close`。\n7. 操作成功后刷新列表或更新当前行状态。\n\n---\n\n#### 管理员查看类型统计\n\n1. 管理员进入统计页面或统计面板。\n2. 调用 `GET /api/admin/feedback/statistics/type`。\n3. `FeedbackTypeStatPanel` 展示四类反馈数量。\n\n---\n\n## 7. 待确认问题\n\n| 编号 | 待确认问题 | 影响范围 | 说明 |\n|---|---|---|---|\n| Q-01 | 反馈编号生成规则是什么？ | 后端、数据库、前端展示 | 当前设计仅要求生成全局唯一编号，具体规则如是否采用“前缀 + 日期 + 序列号”、长度、是否可读等需确认 |\n| Q-02 | 凭编号查询处理进度是否必须校验当前登录用户与反馈归属一致？ | 后端接口、安全设计 | 需求描述为“用户可凭编号查询处理进度”，但未说明是否允许查询非本人反馈，需要确认查询范围 |\n| Q-03 | 普通用户查看自己反馈状态是否需要提供列表页？ | 前端、后端接口 | 当前按角色需求设计了“我的反馈列表”；若仅提供凭编号查询，则可不实现该接口 |\n| Q-04 | 我的反馈列表是否需要筛选条件？ | 前端、后端接口 | 当前仅设计分页；是否需要按状态、类型、时间筛选需确认 |\n| Q-05 | 管理员反馈列表是否需要筛选条件？ | 前端、后端接口 | 当前仅设计分页查看全部反馈；是否需要按编号、标题、类型、状态、时间筛选需确认 |\n| Q-06 | 回复内容是否有长度限制？ | 前端、后端、数据库 | 当前 `reply_content` 使用 `TEXT` 存储，前端与后端长度限制需确认 |\n| Q-07 | 关闭反馈是否需要填写关闭原因或备注？ | 前端、后端、数据库 | 当前关闭操作仅记录关闭时间，未记录关闭原因；是否需要扩展字段需确认 |\n| Q-08 | 回复后反馈状态是“已回复”还是“处理完成”？ | 状态设计、前端展示 | 当前设计为“已回复”；若业务上回复即代表处理完成，可调整状态命名或增加“处理完成”状态 |\n| Q-09 | 已关闭反馈是否允许再次回复或重新打开？ | 状态流转、后端校验 | 当前设计已关闭反馈不允许回复或关闭；是否需要支持重新打开需确认 |\n| Q-10 | 按类型统计是统计全部反馈，还是仅统计待处理、已回复、已关闭中的某类？ | 后端统计 SQL、前端展示 | 当前设计统计全部未删除反馈；是否需要按状态或时间范围统计需确认 |\n| Q-11 | 是否需要记录完整处理操作日志？ | 数据库、后端、前端 | 当前仅记录最后处理人 `handler_id`、`handler_name` 及回复/关闭时间；若需追溯每次回复、关闭操作，需要新增操作日志表 |\n| Q-12 | 管理端是否需要删除反馈功能？ | 前端、后端、数据库 | 当前需求未提出删除功能，`deleted` 字段仅作为基础逻辑删除字段预留 |\n| Q-13 | 是否需要防重复提交？ | 后端、前端 | 例如同一用户短时间内提交相同标题或内容是否需要拦截，需求未说明 |\n| Q-14 | 反馈标题、反馈内容、回复内容是否需要敏感词过滤或内容安全审核？ | 后端、前端 | 需求未说明，需要确认是否接入现有内容安全能力 |\n| Q-15 | 管理员权限如何识别？ | 后端接口权限、前端菜单 | 需要确认使用现有角色权限体系中的哪个权限标识控制管理端接口和页面 |', '', 'admin', '2026-09-02 10:04:04', 'admin', '2026-09-02 11:21:36', b'0');
INSERT INTO `dev_artifact` VALUES (2, 2, 1, 1, 2, '# 我的反馈列表（用户）概要设计文档\n\n## 1. 概述\n\n本需求面向已登录用户，提供“我的反馈”只读列表与详情查看能力，用于分页展示当前用户提交的反馈记录，支持按反馈类型和反馈状态筛选，并支持点击单条反馈查看详情及管理员的处理回复；本设计仅覆盖用户端反馈列表与详情查询，不包含反馈提交、编辑、删除及管理员端处理逻辑。\n\n---\n\n## 2. 功能清单\n\n| 编号 | 功能点 | 功能说明 | 优先级 |\n|---|---|---|---|\n| F-001 | 我的反馈分页列表 | 分页展示当前用户提交的反馈，列表字段包括标题、类型、提交时间、状态 | P0 |\n| F-002 | 按反馈类型筛选 | 支持用户在列表中按反馈类型筛选当前用户提交的反馈 | P0 |\n| F-003 | 按反馈状态筛选 | 支持用户在列表中按反馈状态筛选当前用户提交的反馈 | P0 |\n| F-004 | 查看反馈详情 | 用户点击列表中的反馈后，查看该反馈的详情信息 | P0 |\n| F-005 | 查看管理员处理回复 | 在反馈详情中展示管理员对该反馈的处理回复 | P0 |\n| F-006 | 获取筛选选项 | 提供反馈类型和反馈状态筛选下拉选项；若系统已有统一字典服务，则复用字典接口 | P1 |\n| F-007 | 列表加载与空态展示 | 列表加载、分页切换、无数据时展示空态 | P1 |\n\n---\n\n## 3. 数据库设计\n\n### 3.1 表：`feedback`\n\n用于存储用户提交的反馈信息。本需求中用户端仅查询当前用户创建的反馈，因此通过 `creator` 字段识别当前用户。\n\n| 字段名 | 类型 | 是否必填 | 注释 |\n|---|---:|---:|---|\n| `id` | `BIGINT UNSIGNED` | 是 | 主键 ID，自增 |\n| `creator` | `BIGINT` | 是 | 创建人用户 ID，即当前用户 ID |\n| `create_time` | `DATETIME` | 是 | 创建时间，即反馈提交时间 |\n| `updater` | `BIGINT` | 否 | 更新人用户 ID |\n| `update_time` | `DATETIME` | 否 | 更新时间 |\n| `deleted` | `TINYINT` | 是 | 逻辑删除标识：0 未删除，1 已删除 |\n| `title` | `VARCHAR(128)` | 是 | 反馈标题 |\n| `type` | `TINYINT` | 是 | 反馈类型，具体枚举值待确认 |\n| `content` | `TEXT` | 否 | 反馈正文，用于详情展示；是否所有反馈都有正文待确认 |\n| `status` | `TINYINT` | 是 | 反馈状态，具体枚举值待确认 |\n| `admin_reply` | `TEXT` | 否 | 管理员处理回复 |\n\n### 3.2 索引设计\n\n| 索引名 | 索引字段 | 说明 |\n|---|---|---|\n| `idx_feedback_creator_deleted_status_type_id` | `creator`, `deleted`, `status`, `type`, `id` | 用于当前用户反馈分页查询、状态筛选、类型筛选及组合筛选 |\n\n> 说明：若后续统计发现“仅按类型筛选”场景较多，可增加索引 `idx_feedback_creator_deleted_type_status_id`，字段为 `creator`, `deleted`, `type`, `status`, `id`。\n\n### 3.3 建表 SQL 参考\n\n```sql\nCREATE TABLE `feedback` (\n    `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT \'主键ID\',\n    `creator` BIGINT NOT NULL COMMENT \'创建人用户ID，即当前用户ID\',\n    `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT \'创建时间，即反馈提交时间\',\n    `updater` BIGINT NULL COMMENT \'更新人用户ID\',\n    `update_time` DATETIME NULL ON UPDATE CURRENT_TIMESTAMP COMMENT \'更新时间\',\n    `deleted` TINYINT NOT NULL DEFAULT 0 COMMENT \'逻辑删除标识：0未删除，1已删除\',\n    `title` VARCHAR(128) NOT NULL COMMENT \'反馈标题\',\n    `type` TINYINT NOT NULL COMMENT \'反馈类型，具体枚举值待确认\',\n    `content` TEXT NULL COMMENT \'反馈正文，用于详情展示\',\n    `status` TINYINT NOT NULL COMMENT \'反馈状态，具体枚举值待确认\',\n    `admin_reply` TEXT NULL COMMENT \'管理员处理回复\',\n    PRIMARY KEY (`id`),\n    KEY `idx_feedback_creator_deleted_status_type_id` (`creator`, `deleted`, `status`, `type`, `id`)\n) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = \'用户反馈表\';\n```\n\n---\n\n## 4. 接口设计\n\n### 4.1 统一返回结构\n\n| 字段名 | 类型 | 注释 |\n|---|---|---|\n| `code` | `Integer` | 业务状态码，0 表示成功，非 0 表示失败 |\n| `message` | `String` | 提示信息 |\n| `data` | `T` | 业务数据 |\n\n分页数据结构 `PageResult<T>`：\n\n| 字段名 | 类型 | 注释 |\n|---|---|---|\n| `total` | `Long` | 总记录数 |\n| `list` | `List<T>` | 当前页数据列表 |\n\n---\n\n### 4.2 我的反馈分页查询\n\n| 项目 | 内容 |\n|---|---|\n| 接口路径 | `/api/feedback/my/page` |\n| 请求方式 | `GET` |\n| 功能说明 | 分页查询当前登录用户提交的反馈列表，支持按反馈类型和状态筛选 |\n| 入参 VO | `MyFeedbackPageQueryVO` |\n| 出参 VO | `Result<PageResult<MyFeedbackVO>>` |\n\n#### 入参：`MyFeedbackPageQueryVO`\n\n| 字段名 | 类型 | 必填 | 默认值 | 注释 |\n|---|---|---:|---|---|\n| `pageNum` | `Integer` | 否 | 1 | 页码，最小值为 1 |\n| `pageSize` | `Integer` | 否 | 10 | 每页条数，建议最大值为 50，具体上限待确认 |\n| `type` | `Integer` | 否 | 无 | 反馈类型筛选值，不传表示不筛选 |\n| `status` | `Integer` | 否 | 无 | 反馈状态筛选值，不传表示不筛选 |\n\n#### 出参：`MyFeedbackVO`\n\n| 字段名 | 类型 | 注释 |\n|---|---|---|\n| `id` | `Long` | 反馈 ID |\n| `title` | `String` | 反馈标题 |\n| `type` | `Integer` | 反馈类型原始值 |\n| `typeDesc` | `String` | 反馈类型描述，用于前端展示 |\n| `createTime` | `String` | 提交时间，格式建议为 `yyyy-MM-dd HH:mm:ss` |\n| `status` | `Integer` | 反馈状态原始值 |\n| `statusDesc` | `String` | 反馈状态描述，用于前端展示 |\n\n#### 业务规则\n\n1. 仅查询 `creator` 等于当前登录用户 ID 的数据。\n2. 仅查询 `deleted = 0` 的数据。\n3. 排序规则建议为：`create_time DESC`, `id DESC`。\n4. 若 `type` 或 `status` 传入，则追加对应等值筛选条件。\n\n---\n\n### 4.3 我的反馈详情查询\n\n| 项目 | 内容 |\n|---|---|\n| 接口路径 | `/api/feedback/my/detail` |\n| 请求方式 | `GET` |\n| 功能说明 | 查询当前登录用户提交的某条反馈详情，并返回管理员处理回复 |\n| 入参 VO | `MyFeedbackDetailQueryVO` |\n| 出参 VO | `Result<MyFeedbackDetailVO>` |\n\n#### 入参：`MyFeedbackDetailQueryVO`\n\n| 字段名 | 类型 | 必填 | 注释 |\n|---|---|---:|---|\n| `id` | `Long` | 是 | 反馈 ID |\n\n#### 出参：`MyFeedbackDetailVO`\n\n| 字段名 | 类型 | 注释 |\n|---|---|---|\n| `id` | `Long` | 反馈 ID |\n| `title` | `String` | 反馈标题 |\n| `type` | `Integer` | 反馈类型原始值 |\n| `typeDesc` | `String` | 反馈类型描述 |\n| `content` | `String` | 反馈正文 |\n| `status` | `Integer` | 反馈状态原始值 |\n| `statusDesc` | `String` | 反馈状态描述 |\n| `createTime` | `String` | 提交时间，格式建议为 `yyyy-MM-dd HH:mm:ss` |\n| `adminReply` | `String` | 管理员处理回复，无回复时为空字符串或 `null` |\n\n#### 业务规则\n\n1. 根据 `id` 查询反馈。\n2. 校验反馈 `creator` 是否等于当前登录用户 ID。\n3. 校验反馈 `deleted = 0`。\n4. 若反馈不存在、已删除或不属于当前用户，返回失败提示。\n5. 返回 `admin_reply` 字段作为管理员处理回复。\n\n---\n\n### 4.4 反馈筛选选项查询\n\n> 该接口用于前端下拉筛选。若系统已有统一字典服务，可复用字典接口，不新增本接口；若无统一字典服务，则新增本接口。\n\n| 项目 | 内容 |\n|---|---|\n| 接口路径 | `/api/feedback/my/options` |\n| 请求方式 | `GET` |\n| 功能说明 | 查询反馈类型和反馈状态筛选选项 |\n| 入参 VO | 无 |\n| 出参 VO | `Result<FeedbackOptionVO>` |\n\n#### 出参：`FeedbackOptionVO`\n\n| 字段名 | 类型 | 注释 |\n|---|---|---|\n| `typeOptions` | `List<OptionVO>` | 反馈类型选项列表 |\n| `statusOptions` | `List<OptionVO>` | 反馈状态选项列表 |\n\n#### 出参：`OptionVO`\n\n| 字段名 | 类型 | 注释 |\n|---|---|---|\n| `value` | `Integer` | 选项值，对应数据库 `type` 或 `status` |\n| `label` | `String` | 选项展示名称 |\n\n---\n\n## 5. 后端设计\n\n以下按常见 Spring Boot + MyBatis-Plus 分层进行设计。若项目使用其他技术栈，可按 Controller、Service、DO、Mapper、VO 的职责进行映射。\n\n### 5.1 新增/修改类清单\n\n| 分层 | 类名 | 新增/修改 | 职责说明 |\n|---|---|---|---|\n| Controller | `FeedbackMyController` | 新增 | 暴露用户端“我的反馈”相关接口，包括分页查询、详情查询、筛选选项查询 |\n| Service | `FeedbackMyService` | 新增 | 定义用户端反馈查询服务接口 |\n| ServiceImpl | `FeedbackMyServiceImpl` | 新增 | 实现用户身份识别、数据查询、权限校验、对象转换 |\n| DO | `FeedbackDO` | 新增/修改 | 映射 `feedback` 表，承载数据库字段 |\n| Mapper | `FeedbackMapper` | 新增/修改 | 提供 `feedback` 表数据访问能力 |\n| VO | `MyFeedbackPageQueryVO` | 新增 | 我的反馈分页查询入参 |\n| VO | `MyFeedbackDetailQueryVO` | 新增 | 我的反馈详情查询入参 |\n| VO | `MyFeedbackVO` | 新增 | 我的反馈列表出参 |\n| VO | `MyFeedbackDetailVO` | 新增 | 我的反馈详情出参 |\n| VO | `FeedbackOptionVO` | 新增 | 反馈筛选选项出参 |\n| VO | `OptionVO` | 新增 | 通用下拉选项 |\n| Enum | `FeedbackType` | 新增/修改 | 若采用代码枚举维护反馈类型，则用于类型值与描述转换 |\n| Enum | `FeedbackStatus` | 新增/修改 | 若采用代码枚举维护反馈状态，则用于状态值与描述转换 |\n| Converter | `MyFeedbackConverter` | 新增 | 负责 `FeedbackDO` 与 `MyFeedbackVO`、`MyFeedbackDetailVO` 之间的转换 |\n\n### 5.2 Controller 设计\n\n#### 类名：`FeedbackMyController`\n\n建议路径前缀：`/api/feedback/my`\n\n| 方法 | 路径 | 请求方式 | 入参 | 出参 | 说明 |\n|---|---|---|---|---|---|\n| `page` | `/api/feedback/my/page` | `GET` | `MyFeedbackPageQueryVO` | `Result<PageResult<MyFeedbackVO>>` | 分页查询当前用户反馈 |\n| `detail` | `/api/feedback/my/detail` | `GET` | `MyFeedbackDetailQueryVO` | `Result<MyFeedbackDetailVO>` | 查询当前用户反馈详情 |\n| `options` | `/api/feedback/my/options` | `GET` | 无 | `Result<FeedbackOptionVO>` | 查询筛选选项 |\n\n方法签名参考：\n\n```java\n@GetMapping(\"/page\")\npublic Result<PageResult<MyFeedbackVO>> page(@Valid MyFeedbackPageQueryVO query) {\n    return Result.success(feedbackMyService.pageMyFeedback(query));\n}\n\n@GetMapping(\"/detail\")\npublic Result<MyFeedbackDetailVO> detail(@Valid MyFeedbackDetailQueryVO query) {\n    return Result.success(feedbackMyService.getMyFeedbackDetail(query.getId()));\n}\n\n@GetMapping(\"/options\")\npublic Result<FeedbackOptionVO> options() {\n    return Result.success(feedbackMyService.getFeedbackOptions());\n}\n```\n\n### 5.3 Service 设计\n\n#### 接口：`FeedbackMyService`\n\n| 方法 | 入参 | 出参 | 说明 |\n|---|---|---|---|\n| `pageMyFeedback` | `MyFeedbackPageQueryVO` | `PageResult<MyFeedbackVO>` | 分页查询当前用户反馈列表 |\n| `getMyFeedbackDetail` | `Long id` | `MyFeedbackDetailVO` | 查询当前用户反馈详情 |\n| `getFeedbackOptions` | 无 | `FeedbackOptionVO` | 查询反馈类型和状态选项 |\n\n#### 实现：`FeedbackMyServiceImpl`\n\n核心职责：\n\n1. 获取当前登录用户 ID。\n2. 构造查询条件：`creator = 当前用户ID`、`deleted = 0`。\n3. 根据入参追加 `type`、`status` 筛选条件。\n4. 按 `create_time DESC`, `id DESC` 排序。\n5. 查询结果转换为 VO。\n6. 详情查询时校验反馈是否属于当前用户。\n7. 将 `type`、`status` 原始值转换为 `typeDesc`、`statusDesc`。\n\n伪代码示例：\n\n```java\npublic PageResult<MyFeedbackVO> pageMyFeedback(MyFeedbackPageQueryVO query) {\n    Long currentUserId = CurrentUserContext.getUserId();\n\n    LambdaQueryWrapper<FeedbackDO> wrapper = new LambdaQueryWrapper<>();\n    wrapper.eq(FeedbackDO::getCreator, currentUserId)\n           .eq(FeedbackDO::getDeleted, 0)\n           .eq(query.getType() != null, FeedbackDO::getType, query.getType())\n           .eq(query.getStatus() != null, FeedbackDO::getStatus, query.getStatus())\n           .orderByDesc(FeedbackDO::getCreateTime)\n           .orderByDesc(FeedbackDO::getId);\n\n    Page<FeedbackDO> page = feedbackMapper.selectPage(\n        new Page<>(query.getPageNum(), query.getPageSize()),\n        wrapper\n    );\n\n    List<MyFeedbackVO> voList = MyFeedbackConverter.toListVO(page.getRecords());\n    return new PageResult<>(page.getTotal(), voList);\n}\n```\n\n### 5.4 DO 设计\n\n#### 类名：`FeedbackDO`\n\n对应表：`feedback`\n\n| Java 字段 | 数据库字段 | 类型 | 说明 |\n|---|---|---|---|\n| `id` | `id` | `Long` | 主键 ID |\n| `creator` | `creator` | `Long` | 创建人用户 ID |\n| `createTime` | `create_time` | `LocalDateTime` | 创建时间 |\n| `updater` | `updater` | `Long` | 更新人用户 ID |\n| `updateTime` | `update_time` | `LocalDateTime` | 更新时间 |\n| `deleted` | `deleted` | `Integer` | 逻辑删除标识 |\n| `title` | `title` | `String` | 反馈标题 |\n| `type` | `type` | `Integer` | 反馈类型 |\n| `content` | `content` | `String` | 反馈正文 |\n| `status` | `status` | `Integer` | 反馈状态 |\n| `adminReply` | `admin_reply` | `String` | 管理员处理回复 |\n\n### 5.5 Mapper 设计\n\n#### 类名：`FeedbackMapper`\n\n建议继承 MyBatis-Plus `BaseMapper<FeedbackDO>`。\n\n| 方法 | 说明 |\n|---|---|\n| `selectPage` | 继承自 `BaseMapper`，用于分页查询 |\n| `selectById` | 继承自 `BaseMapper`，用于详情查询 |\n| `selectByCreatorAndId` | 可选自定义方法，用于按当前用户和 ID 查询，增强归属校验语义 |\n\n自定义方法参考：\n\n```java\nFeedbackDO selectByCreatorAndId(@Param(\"creator\") Long creator, @Param(\"id\") Long id);\n```\n\n对应 SQL 参考：\n\n```sql\nSELECT *\nFROM feedback\nWHERE creator = #{creator}\n  AND id = #{id}\n  AND deleted = 0;\n```\n\n### 5.6 VO 设计\n\n#### `MyFeedbackPageQueryVO`\n\n| 字段名 | 类型 | 校验 | 说明 |\n|---|---|---|---|\n| `pageNum` | `Integer` | `@Min(1)` | 页码 |\n| `pageSize` | `Integer` | `@Min(1)`，建议 `@Max(50)` | 每页条数 |\n| `type` | `Integer` | 可选 | 反馈类型筛选值 |\n| `status` | `Integer` | 可选 | 反馈状态筛选值 |\n\n#### `MyFeedbackDetailQueryVO`\n\n| 字段名 | 类型 | 校验 | 说明 |\n|---|---|---|---|\n| `id` | `Long` | `@NotNull` | 反馈 ID |\n\n#### `MyFeedbackVO`\n\n| 字段名 | 类型 | 说明 |\n|---|---|---|\n| `id` | `Long` | 反馈 ID |\n| `title` | `String` | 反馈标题 |\n| `type` | `Integer` | 反馈类型原始值 |\n| `typeDesc` | `String` | 反馈类型描述 |\n| `createTime` | `String` | 提交时间 |\n| `status` | `Integer` | 反馈状态原始值 |\n| `statusDesc` | `String` | 反馈状态描述 |\n\n#### `MyFeedbackDetailVO`\n\n| 字段名 | 类型 | 说明 |\n|---|---|---|\n| `id` | `Long` | 反馈 ID |\n| `title` | `String` | 反馈标题 |\n| `type` | `Integer` | 反馈类型原始值 |\n| `typeDesc` | `String` | 反馈类型描述 |\n| `content` | `String` | 反馈正文 |\n| `status` | `Integer` | 反馈状态原始值 |\n| `statusDesc` | `String` | 反馈状态描述 |\n| `createTime` | `String` | 提交时间 |\n| `adminReply` | `String` | 管理员处理回复 |\n\n#### `FeedbackOptionVO`\n\n| 字段名 | 类型 | 说明 |\n|---|---|---|\n| `typeOptions` | `List<OptionVO>` | 反馈类型选项 |\n| `statusOptions` | `List<OptionVO>` | 反馈状态选项 |\n\n#### `OptionVO`\n\n| 字段名 | 类型 | 说明 |\n|---|---|---|\n| `value` | `Integer` | 选项值 |\n| `label` | `String` | 选项名称 |\n\n### 5.7 枚举设计\n\n> 具体枚举值待确认。若系统已有字典服务，可不新增枚举，改为从字典服务获取选项和描述。\n\n#### `FeedbackType`\n\n| 字段 | 类型 | 说明 |\n|---|---|---|\n| `value` | `Integer` | 类型值 |\n| `desc` | `String` | 类型描述 |\n\n建议提供方法：\n\n```java\npublic static FeedbackType fromValue(Integer value);\npublic String getDesc();\n```\n\n#### `FeedbackStatus`\n\n| 字段 | 类型 | 说明 |\n|---|---|---|\n| `value` | `Integer` | 状态值 |\n| `desc` | `String` | 状态描述 |\n\n建议提供方法：\n\n```java\npublic static FeedbackStatus fromValue(Integer value);\npublic String getDesc();\n```\n\n### 5.8 Converter 设计\n\n#### 类名：`MyFeedbackConverter`\n\n职责：\n\n1. `FeedbackDO` 转 `MyFeedbackVO`。\n2. `FeedbackDO` 转 `MyFeedbackDetailVO`。\n3. 将 `type` 转换为 `typeDesc`。\n4. 将 `status` 转换为 `statusDesc`。\n5. 将 `createTime` 格式化为 `yyyy-MM-dd HH:mm:ss`。\n6. `adminReply` 为空时返回空字符串，便于前端统一展示。\n\n方法参考：\n\n```java\npublic static MyFeedbackVO toListVO(FeedbackDO feedbackDO);\npublic static List<MyFeedbackVO> toListVO(List<FeedbackDO> feedbackDOList);\npublic static MyFeedbackDetailVO toDetailVO(FeedbackDO feedbackDO);\n```\n\n---\n\n## 6. 前端设计\n\n### 6.1 页面与组件\n\n| 类型 | 名称 | 路由/位置 | 说明 |\n|---|---|---|---|\n| 页面 | `MyFeedbackListPage` | `/my-feedback` | 我的反馈列表页，包含筛选区、列表区、分页区、详情弹窗 |\n| 组件 | `FeedbackFilterForm` | `MyFeedbackListPage` 内 | 反馈类型、反馈状态筛选表单 |\n| 组件 | `MyFeedbackTable` | `MyFeedbackListPage` 内 | 我的反馈列表表格 |\n| 组件 | `FeedbackDetailModal` | `MyFeedbackListPage` 内 | 反馈详情弹窗 |\n| 组件 | `Pagination` | `MyFeedbackListPage` 内 | 分页组件，可复用项目已有分页组件 |\n\n### 6.2 页面功能说明\n\n#### `MyFeedbackListPage`\n\n页面职责：\n\n1. 页面初始化时加载反馈类型和状态筛选选项。\n2. 页面初始化时调用分页接口查询第一页数据。\n3. 用户点击“查询”时，携带 `type`、`status`、`pageNum`、`pageSize` 调用分页接口。\n4. 用户点击“重置”时，清空筛选条件，并重新查询第一页。\n5. 用户点击表格中的“查看”或标题时，打开 `FeedbackDetailModal`。\n6. 分页组件变化时，重新调用分页接口。\n\n#### `FeedbackFilterForm`\n\n表单字段：\n\n| 字段名 | 控件类型 | 数据来源 | 说明 |\n|---|---|---|---|\n| `type` | 下拉选择 | `/api/feedback/my/options` 或字典接口 | 反馈类型筛选 |\n| `status` | 下拉选择 | `/api/feedback/my/options` 或字典接口 | 反馈状态筛选 |\n\n按钮：\n\n| 按钮 | 操作 |\n|---|---|\n| 查询 | 触发列表查询，`pageNum` 重置为 1 |\n| 重置 | 清空 `type`、`status`，触发列表查询，`pageNum` 重置为 1 |\n\n#### `MyFeedbackTable`\n\n表格列：\n\n| 列名 | 字段 | 说明 |\n|---|---|---|\n| 标题 | `title` | 可点击，点击后打开详情弹窗 |\n| 类型 | `typeDesc` | 展示反馈类型描述 |\n| 提交时间 | `createTime` | 展示反馈提交时间 |\n| 状态 | `statusDesc` | 展示反馈状态描述 |\n| 操作 | - | 提供“查看”按钮 |\n\n分页参数：\n\n| 参数 | 说明 |\n|---|---|\n| `pageNum` | 当前页码 |\n| `pageSize` | 每页条数 |\n| `total` | 总记录数 |\n\n#### `FeedbackDetailModal`\n\n弹窗触发方式：\n\n1. 点击列表标题。\n2. 点击操作列“查看”。\n\n弹窗展示字段：\n\n| 字段名 | 字段 | 说明 |\n|---|---|---|\n| 标题 | `title` | 反馈标题 |\n| 类型 | `typeDesc` | 反馈类型 |\n| 状态 | `statusDesc` | 反馈状态 |\n| 提交时间 | `createTime` | 反馈提交时间 |\n| 反馈内容 | `content` | 反馈正文，若为空可展示“暂无内容” |\n| 管理员处理回复 | `adminReply` | 管理员回复，若为空展示“暂无回复” |\n\n弹窗关闭后，不刷新列表，除非产品要求刷新。\n\n### 6.3 前端接口对应关系\n\n| 前端位置 | 调用接口 | 触发时机 | 说明 |\n|---|---|---|---|\n| `MyFeedbackListPage` | `GET /api/feedback/my/page` | 页面初始化 | 加载第一页反馈列表 |\n| `FeedbackFilterForm` | `GET /api/feedback/my/page` | 点击查询 | 按类型、状态筛选 |\n| `FeedbackFilterForm` | `GET /api/feedback/my/page` | 点击重置 | 清空筛选条件并重新查询 |\n| `Pagination` | `GET /api/feedback/my/page` | 切换页码或每页条数 | 分页查询 |\n| `MyFeedbackTable` | `GET /api/feedback/my/detail` | 点击标题或查看 | 打开详情弹窗前或弹窗打开时查询详情 |\n| `FeedbackFilterForm` | `GET /api/feedback/my/options` | 页面初始化 | 加载类型和状态筛选选项；若使用字典接口则替换为字典接口 |\n\n### 6.4 前端展示规则\n\n1. 类型和状态统一展示 `typeDesc`、`statusDesc`，不直接展示原始值。\n2. 提交时间展示格式为 `yyyy-MM-dd HH:mm:ss`。\n3. 列表无数据时展示空态，例如“暂无反馈记录”。\n4. 详情中 `content` 为空时展示“暂无内容”。\n5. 详情中 `adminReply` 为空时展示“暂无回复”。\n6. 筛选条件变化后，页码应重置为 1。\n7. 详情查询失败时，弹窗内展示错误提示，例如“反馈不存在”或“暂无权限查看”。\n\n---\n\n## 7. 待确认问题\n\n| 编号 | 待确认问题 | 影响范围 |\n|---|---|---|\n| Q-001 | 当前登录用户 ID 的获取方式是什么？是否已有统一登录上下文？用户 ID 是 `Long` 还是 `String`？ | 后端 `creator` 查询、权限校验、数据库字段类型 |\n| Q-002 | `feedback` 表是否已存在？若已存在，当前字段结构是否满足本设计？ | 数据库新增或修改 |\n| Q-003 | 反馈类型 `type` 的具体枚举值、名称及维护方式是什么？是代码枚举、配置表还是统一字典？ | 数据库字段、接口选项、前端下拉、类型描述展示 |\n| Q-004 | 反馈状态 `status` 的具体枚举值、名称及默认值是什么？管理员回复后状态是否变化？ | 数据库字段、状态筛选、状态描述展示 |\n| Q-005 | 反馈详情是否需要展示反馈正文 `content`？若需要，是否所有历史反馈数据都有正文？ | 数据库字段、详情接口出参、前端详情展示 |\n| Q-006 | 管理员处理回复 `admin_reply` 是单条还是多条？是否需要展示管理员回复时间？ | 数据库字段、详情接口出参、前端详情展示 |\n| Q-007 | 前端筛选选项是否已有统一字典接口？若无，是否新增 `/api/feedback/my/options`？ | 接口设计、前端下拉选项来源 |\n| Q-008 | 分页默认每页条数和最大每页条数是多少？ | 分页接口入参校验、前端分页组件 |\n| Q-009 | 接口路径前缀、统一返回结构、业务错误码是否已有项目规范？ | 接口路径、返回结构、异常处理 |\n| Q-010 | 详情查询时，若反馈不属于当前用户，应返回“不存在”还是“无权限”？ | 后端异常处理、前端提示文案 |\n| Q-011 | 列表是否需要展示管理员回复摘要？当前需求仅要求详情展示回复，列表是否只展示标题、类型、提交时间、状态？ | 列表接口出参、前端表格列 |\n| Q-012 | 是否需要多租户、部门、组织等额外数据隔离维度？当前设计仅按 `creator` 隔离。 | 数据库查询条件、权限校验 |', '', 'admin', '2026-09-02 10:30:26', 'admin', '2026-09-02 11:17:08', b'0');

-- ----------------------------
-- Table structure for dev_project
-- ----------------------------
DROP TABLE IF EXISTS `dev_project`;
CREATE TABLE `dev_project`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务名称',
  `requirement_content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '需求文档内容',
  `stage` tinyint NOT NULL DEFAULT 0 COMMENT '当前阶段：0-需求已录入 1-设计评审中 2-设计已定稿 3-代码生成中 4-代码已定稿 5-使用说明已生成',
  `target_project` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '代码生成阶段绑定的目标项目名称',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'AI 开发任务' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of dev_project
-- ----------------------------
INSERT INTO `dev_project` VALUES (1, '用户反馈管理模块', '# 用户反馈管理模块需求文档\n\n## 背景\n\n系统目前没有统一的用户反馈渠道，用户在使用过程中遇到问题或建议只能通过客服电话反馈，\n信息分散、无法追溯。需要开发一个用户反馈管理模块，支持用户提交反馈、管理员查看和处理反馈。\n\n## 用户角色\n\n- 普通用户：提交反馈、查看自己提交的反馈状态\n- 管理员：查看全部反馈、处理（回复/关闭）反馈、按类型统计\n\n## 功能需求\n\n### 提交反馈（用户）\n- 必填：反馈标题（不超过 50 字）、反馈内容（不超过 1000 字）、反馈类型\n- 反馈类型分为：功能异常、体验问题、功能建议、其他\n- 提交成功后生成反馈编号，用户可凭编号查询处理进度', 2, '', 'admin', '2026-09-02 09:48:09', '', '2026-09-02 11:21:36', b'0');
INSERT INTO `dev_project` VALUES (2, '反馈', '### 我的反馈列表（用户）\n- 分页展示当前用户提交的反馈：标题、类型、提交时间、状态\n- 支持按反馈类型和状态筛选\n- 点击可查看详情及管理员的处理回复', 2, 'agent-test', 'admin', '2026-09-02 10:24:12', '', '2026-09-02 11:38:44', b'0');

SET FOREIGN_KEY_CHECKS = 1;
